sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:César_and_Rosalie dbr:Beatrice_(1987_film) }

  ?film dbo:director ?director .

  OPTIONAL { ?director dbp:birthDate ?birthDateDBP . }
  OPTIONAL { ?director dbo:birthDate ?birthDateDBO . }
  BIND (COALESCE(?birthDateDBP, ?birthDateDBO) AS ?birthDate)
}
LIMIT 100

